BEGIN;

-- 1. Alterar tabla athenea_pacientes para agregar columna empresa
ALTER TABLE athenea_pacientes ADD COLUMN IF NOT EXISTS empresa TEXT;

-- 2. Actualizar pacientes demo deterministas con sus empresas reales
UPDATE athenea_pacientes SET empresa = 'Acerías Paz del Río S.A.' WHERE numero_documento = '1049632145';
UPDATE athenea_pacientes SET empresa = 'Cementos Argos S.A.' WHERE numero_documento = '7175482';
UPDATE athenea_pacientes SET empresa = 'Estudiante / No Aplica' WHERE numero_documento = '1052398761';
UPDATE athenea_pacientes SET empresa = 'Postobón S.A.' WHERE numero_documento = '23556789';

-- 3. Asignar empresas aleatorias a los 400 pacientes existentes que tengan empresa NULL
WITH empresas_list AS (
    SELECT ARRAY[
        'Acerías Paz del Río S.A.',
        'Postobón S.A.',
        'Bavaria & Cía S.C.A.',
        'Cementos Argos S.A.',
        'Ecopetrol S.A.',
        'Grupo Nutresa S.A.S.',
        'Alcaldía Mayor de Tunja',
        'Gobernación de Boyacá',
        'Carvajal Tecnología y Servicios S.A.S.',
        'Empresa de Energía de Boyacá (EBSA)',
        'Holcim Colombia S.A.',
        'Comfaboy',
        'Hospital Universitario San Rafael de Tunja',
        'Servientrega S.A.',
        'D1 S.A.S. (Koba Colombia)',
        'Almacenes Éxito S.A.',
        'Transportes Concorde S.A.',
        'Coflonorte / Libertadores S.A.',
        'Lácteos La Alquería Boyacá',
        'Mina El Cerrejón / Carbones de Boyacá'
    ] AS arr
)
UPDATE athenea_pacientes
SET empresa = (
    SELECT arr[1 + floor(random() * array_length(arr, 1))::int]
    FROM empresas_list
)
WHERE empresa IS NULL;

-- 4. Insertar 100 nuevos pacientes trabajadores para Salud Ocupacional / Examen de Ingreso
